(function(root){
const definitions=[['assets','資產統計',true],['risk','槓桿風險',true],['capacity','可扛跌幅',true],['scenario','下跌情境',false],['brokers','券商明細',false],['interest','半年質押利息',false],['tax','遺產稅估算',false]];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>Number.isFinite(n)?n.toLocaleString('zh-TW',{maximumFractionDigits:2}):'—',money=n=>fmt(n)+' 萬',cap=n=>n===null?'無借款':fmt(n*100)+'%';
function level(n){return n===null?{label:'淨資產非正',tone:'high'}:n<=1.5?{label:'曝險較低',tone:'low'}:n<=2?{label:'需要留意',tone:'mid'}:{label:'曝險較高',tone:'high'};}
function build(family,opts={},date='',drop=.2){const members=family.filter((m,i)=>!opts.members||opts.members.includes(i));if(!members.length)throw Error('請至少選一位成員');if(!definitions.some(([k])=>opts[k]))throw Error('請至少選一項資訊');
const data=members.map(m=>{root.RiskEngine.validate(m.data);return {m,r:root.RiskEngine.calculate(m.data),c:root.RiskEngine.capacity(m.data),v:root.RiskEngine.readiness(m.data,drop)};}),sum=k=>data.reduce((n,d)=>n+(k==='cash'?d.m.data.cash:d.r[k]),0);const metric=(n,v)=>`<div class="rr-metric"><span>${n}</span><strong>${v}</strong></div>`;
let html=`<article class="rr"><header class="rr-head"><div><span class="rr-eyebrow">FAMILY WEALTH / 家族資產</span><h1>資產與風險報告</h1></div><div class="rr-date">${esc(date)}<br>${members.length} 位成員 · 萬元</div></header>`;
if(opts.assets){const stock=sum('stock'),cash=sum('cash'),assets=stock+cash,share=assets>0?stock/assets*100:0;html+=`<section class="rr-hero"><div><span>所選成員淨資產</span><strong>${money(sum('equity'))}</strong><div class="rr-mini">${metric('股票市值',money(stock))}${metric('可用現金',money(cash))}${metric('總借款',money(sum('debt')))}</div></div><div class="rr-composition"><div class="rr-donut" style="background:conic-gradient(#26b6a2 ${share}%,#d4e8eb 0)"><span>${fmt(share)}%<small>股票占資產</small></span></div><small>股票＋現金 ${money(assets)}</small></div></section>`;}
html+=`<div class="rr-members">${data.map(d=>{const l=level(d.r.leverage),current=d.c.current===null?'無借款':d.c.current<=0?'已達保守門檻':d.c.current<.1?'緩衝偏薄':'尚有下跌緩衝';let body='';if(opts.assets)body+=`<div class="rr-member-assets">${metric('淨資產',money(d.r.equity))}${metric('股票',money(d.r.stock))}${metric('借款',money(d.r.debt))}${metric('現金',money(d.m.data.cash))}</div>`;
if(opts.risk)body+=`<div class="rr-risk"><div><span>股票曝險倍數</span><strong>${d.r.leverage===null?'—':fmt(d.r.leverage)+'<small> 倍</small>'}</strong><span class="rr-badge ${l.tone}">${l.label}</span></div><div class="rr-sensitivity"><span>股票下跌 10%</span><strong>淨資產約減少 ${d.r.leverage===null?'—':fmt(d.r.leverage*10)+'%'}</strong><span>${current}</span></div></div>`;
if(opts.capacity)body+=`<div class="rr-capacity"><h3>最多可扛多少下跌</h3>${[['原部位',d.c.current,'base'],['先用現金',d.c.cashOnly,'cash'],['最後加現股',d.c.cash,'stock']].map(([n,v,k])=>`<div class="rr-stage"><span>${n}</span><div class="rr-track"><i class="${k}" style="width:${v===null?0:Math.max(0,Math.min(100,v*100))}%"></i></div><strong>${cap(v)}</strong></div>`).join('')}</div>`;
if(opts.scenario)body+=`<div class="rr-scenario"><h3>股票下跌 ${fmt(drop*100)}%</h3><strong>${esc(d.v.label)}</strong><div class="rr-member-assets">${metric('情境淨資產',money(d.v.original.equity))}${metric('需還本金',money(d.v.original.repay))}${metric('先用現金',money(d.v.cashUsed))}${metric('加現股仍缺',money(d.v.support.cashGap))}</div></div>`;
if(opts.brokers)body+=`<h3>券商明細</h3><div class="rr-table"><table><thead><tr><th>券商</th><th>現金</th><th>現股</th><th>質押市值／借款</th><th>融資市值／借款</th></tr></thead><tbody>${d.m.data.pools.map(p=>`<tr><td>${esc(p.name)}</td><td>${fmt(p.cash)}</td><td>${fmt(p.other)}</td><td>${fmt(p.pledgeValue)}／${fmt(p.pledgeDebt)}</td><td>${fmt(p.marginValue)}／${fmt(p.marginDebt)}</td></tr>`).join('')}</tbody></table></div>`;
if(opts.interest){const ps=d.m.data.pools.filter(p=>p.pledgeDebt>0),missing=ps.filter(p=>root.RiskPlanning.interest(p)===null).length,total=ps.reduce((n,p)=>n+(root.RiskPlanning.interest(p)??0),0);body+=`<div class="rr-extra">${metric('半年質押利息'+(missing?'（已填部分）':''),money(total))}${metric('每月預留',missing?'尚有利率待填':money(total/6))}</div>`;}
if(opts.tax){const t=root.RiskPlanning.estate(d.m.data,root.RiskPlanning.normalize(d.m.planning??{}).estate);body+=`<div class="rr-extra">${metric('估計遺產稅',money(t.tax))}${metric('課稅淨額',money(t.taxable))}</div>`;}
return `<section class="rr-member"><div class="rr-member-head"><h2>${esc(d.m.name)}</h2>${opts.capacity?'<span class="rr-badge '+(d.c.current!==null&&d.c.current<.1?'mid':'low')+'">'+current+'</span>':''}</div>${body}${d.m.data.pools.some(p=>p.legacyCombined)?'<small class="rr-warning">舊合計部位待核對質押／融資拆分</small>':''}</section>`;}).join('')}</div>`;
html+=`<footer class="rr-foot">${opts.risk?'曝險分級：≤1.5倍較低、≤2倍需留意、＞2倍較高，僅供本工具比較。 ':''}${opts.capacity||opts.scenario?`保守門檻：質押${root.RiskEngine.policy().pledge}%／融資130%；股票同步下跌，同人現金共用，現股不跨券商。 `:''}試算不代表安全保證。${opts.tax?'遺產稅採2026年規則及已填扣除資料，正式申報以繼承日價值為準。':''}</footer></article>`;return html;}
root.RiskReport={definitions,build,level};if(typeof module!=='undefined')module.exports=root.RiskReport;
})(globalThis);
